/* Differential on genuine ordinary campaigns. No authored actors, cash,
 * research, HP, map, schedule, AI, time changes or input. Natural AI supplies
 * firing, cargo, actual refinery income and scheduled enemy/player waves. */
#define GENESIS_NO_MAIN
#include "../.local/source/build/dune-base.c"
#define EMSCRIPTEN_KEEPALIVE
#define EM_WEB_SELECTION_NO_SCREEN
static CPU em_cpu,oracle,initial;
static struct{int paused,stopped;DuneMouse dune_mouse;}em_host;
static int em_window=1;
#include "em_web_selection.h"
#include "em_web_menus.h"
#include "em_web_menu_select.h"
#include "em_web_campaign.h"
#include <sys/stat.h>
#include <time.h>
typedef struct{unsigned flags,hp,type,owner;}Actor;
typedef struct{uint64_t frames,shots,projectiles,hp_decreases,harvest_adds,cargo_added,deliveries,credits_delivered,waves;unsigned wave_owner_mask,harvest_owner_mask,delivery_owner_mask;uint64_t first_wave_tick,ground_arrivals;unsigned ground_owner_mask,delivery_house,delivery_start_bank;}Evidence;
static Evidence e;static Actor previous[175];static unsigned tracked_owner[102],tracked_type[102];static FILE*events;static unsigned house;static uint64_t source_ticks,source_frames;
static void check(int v,const char*m){if(!v){fprintf(stderr,"FAIL H%u %s pc%x/%x frame%llu/%llu reason%s\n",house,m,oracle.pc,em_cpu.pc,(unsigned long long)oracle.vdp.frames,(unsigned long long)em_cpu.vdp.frames,em_cpu.reason?em_cpu.reason:"");exit(1);}}
static unsigned unit(unsigned id){return 0x1000+id*140;}
static unsigned house_record(const CPU*c,unsigned owner){return (dune_long(c,0xdc24)&65535)+owner*70;}
static void load(unsigned h){house=h;char p[256];snprintf(p,sizeof p,".local/campaign-fixtures/house%u-mission09.cpu.bin",h);FILE*f=fopen(p,"rb");check(f&&fread(&em_cpu,sizeof em_cpu,1,f)==1&&fgetc(f)==EOF,"genuine full CPU snapshot");fclose(f);em_cpu.rom=rom_data;em_cpu.rom_size=sizeof rom_data;em_cpu.reason=NULL;em_cpu.fault=0;em_cpu.audio_mode=AUDIO_MUTE;memset(em_cpu.pad_buttons,0,sizeof em_cpu.pad_buttons);check(dune_word(&em_cpu,0xc274)==house&&dune_word(&em_cpu,0xc050)==8&&dune_mouse_context(&em_cpu)==1,"genuine requested house mission9 map");memset(&em_host,0,sizeof em_host);em_host.dune_mouse.enabled=1;}
static void reset_adapter(void){memset(&em_web_selection,0,sizeof em_web_selection);em_web_menu_select_reset_state();em_web_menu_release_pending=0;memset(&em_web_campaign,0,sizeof em_web_campaign);em_web_campaign_after_load(&em_cpu);memset(&em_host,0,sizeof em_host);em_host.dune_mouse.enabled=1;}
static void event(const CPU*c,const char*kind,unsigned owner,unsigned actor,unsigned value);
static void sample_hp(const CPU*c,int count){for(unsigned i=0;i<175;i++){unsigned a=i<102?unit(i):0x4eb8+(i-102)*98;Actor n={dune_word(c,a+4),dune_word(c,a+18),c->ram[a+2],c->ram[a+8]};Actor p=previous[i];if(count&&(n.flags&3)==3&&(p.flags&3)==3&&n.type==p.type&&n.owner==p.owner&&n.hp<p.hp&&(i>=102||n.type<18||n.type==25))++e.hp_decreases;previous[i]=n;if(count&&i<102&&tracked_owner[i]&&(n.flags&7)==3&&n.owner+1==tracked_owner[i]&&n.type==tracked_type[i]){++e.ground_arrivals;e.ground_owner_mask|=1u<<n.owner;tracked_owner[i]=0;event(c,"scheduled-ground-arrival",n.owner,0xff0000u+a,n.type);}}}
static void event(const CPU*c,const char*kind,unsigned owner,unsigned actor,unsigned value){if(events)fprintf(events,"{\"kind\":\"%s\",\"house\":%u,\"sourceHouse\":%u,\"actor\":%u,\"value\":%u,\"pc\":%u,\"nativeFrame\":%llu,\"nativeTick\":%u}\n",kind,owner,house,actor,value,c->pc,(unsigned long long)c->vdp.frames,dune_long(c,0xc598));}
static void native_step(CPU*c){unsigned pc=c->pc,a=0,old=0;int harvest=0,delivery=0;if(pc==0x48352)++e.shots;if(pc==0x483e6||pc==0x484dc){a=c->a[0]&65535;if(c->a[0]>=0xff1000&&c->a[0]<0xff47c8&&(dune_word(c,a+4)&1)&&c->ram[a+2]>=18&&c->ram[a+2]<=24){++e.projectiles;if(e.projectiles<=8)event(c,"projectile",c->ram[a+8],c->a[0],c->ram[a+2]);}}
 if(pc==0x45b26){a=c->a[2]&65535;harvest=a>=0x1000&&a<0x47c8&&c->ram[a+2]==16&&(dune_word(c,a+4)&1);old=c->ram[a+94];}
 if(pc==0xd06c){unsigned refinery=dune_long(c,0xd5ac)&65535;e.delivery_house=c->ram[refinery+8];if(e.delivery_house<6)e.delivery_start_bank=dune_long(c,house_record(c,e.delivery_house)+18);}
 if(pc==0xd1b6){a=c->a[3]&65535;delivery=a>=0x1000&&a<0x47c8&&c->ram[a+2]==16;old=c->ram[a+94];}
 if(pc==0x239fe&&(c->d[5]&65535)){unsigned p=c->a[4],u=p&65535;if(p>=0xff1000&&p<0xff47c8){++e.waves;unsigned owner=c->ram[u+8];e.wave_owner_mask|=1u<<owner;unsigned id=(u-0x1000)/140;if(id<102){tracked_owner[id]=owner+1;tracked_type[id]=c->ram[u+2];}if(!e.first_wave_tick)e.first_wave_tick=dune_long(c,0xc598);event(c,"scheduled-deployment-accepted",owner,p,c->ram[u+2]);}}
 machine_step(c);
 if(harvest&&c->ram[a+94]>old){++e.harvest_adds;e.cargo_added+=c->ram[a+94]-old;e.harvest_owner_mask|=1u<<c->ram[a+8];if(e.harvest_adds<=8)event(c,"actual-cargo-increase",c->ram[a+8],0xff0000u+a,c->ram[a+94]-old);}
 if(delivery&&c->ram[a+94]<old&&e.delivery_house<6){unsigned bank=dune_long(c,house_record(c,e.delivery_house)+18);if(bank>e.delivery_start_bank){++e.deliveries;e.credits_delivered+=bank-e.delivery_start_bank;e.delivery_owner_mask|=1u<<e.delivery_house;if(e.deliveries<=8)event(c,"actual-refinery-cargo-to-credits",e.delivery_house,0xff0000u+a,bank-e.delivery_start_bank);}}
}
static void compare(void){if(memcmp(&oracle,&em_cpu,sizeof oracle)){const uint8_t*a=(const uint8_t*)&oracle,*b=(const uint8_t*)&em_cpu;size_t at=0;while(at<sizeof oracle&&a[at]==b[at])++at;fprintf(stderr,"first CPU byte difference%zu original%02x adapted%02x RAMbase%zu\n",at,a[at],b[at],offsetof(CPU,ram));check(0,"whole native CPU/device/frame bytes diverged");}}
static void differential(const char*id,unsigned max_frames,int require_wave){initial=em_cpu;oracle=em_cpu;reset_adapter();memset(&e,0,sizeof e);memset(tracked_owner,0,sizeof tracked_owner);sample_hp(&oracle,0);source_ticks=dune_long(&oracle,0xc598);source_frames=oracle.vdp.frames;char p[256];snprintf(p,sizeof p,".local/native-campaign-fidelity/%s.events.jsonl",id);events=fopen(p,"w");check(events!=NULL,"events evidence");uint64_t target=source_frames+max_frames;while(oracle.vdp.frames<target){uint64_t next=oracle.vdp.frames+1;while(!oracle.fault&&oracle.vdp.frames<next)native_step(&oracle);while(!em_cpu.fault&&em_cpu.vdp.frames<next){if(!em_web_campaign_observe(&em_cpu)){em_web_selection_observe();if(!em_web_menus_observe(&em_host.dune_mouse,&em_cpu)&&!em_web_menu_select_observe(&em_host.dune_mouse,&em_cpu))dune_mouse_observe(&em_host.dune_mouse,&em_cpu);}machine_step(&em_cpu);}check(!oracle.fault&&!em_cpu.fault,"ordinary native execution fault-free");compare();++e.frames;sample_hp(&oracle,1);if(e.frames%6000==0){printf("TRACE %s frame+%llu nativeTicks+%u fire%llu projectiles%llu HP%llu cargo%llu deliveries%llu waves%llu\n",id,(unsigned long long)e.frames,dune_long(&oracle,0xc598)-(unsigned)source_ticks,(unsigned long long)e.shots,(unsigned long long)e.projectiles,(unsigned long long)e.hp_decreases,(unsigned long long)e.harvest_adds,(unsigned long long)e.deliveries,(unsigned long long)e.waves);fflush(stdout);}if(require_wave&&e.waves>=4&&e.projectiles&&e.hp_decreases&&(e.ground_owner_mask&(1u<<house)))break;if(!require_wave&&e.harvest_adds&&e.deliveries)break;}
 fclose(events);events=NULL;check(e.frames>100,"meaningful continuous frame coverage");if(require_wave){check(e.harvest_adds&&e.deliveries&&e.credits_delivered,"natural native AI cargo and actual refinery income");check((e.ground_owner_mask&(1u<<house))||em_web_campaign.outcome==2,"native own-color ground arrival or honest unmodified defeat before arrival");check(e.projectiles&&e.hp_decreases,"actual original firing/projectiles and actor HP loss observed");check(e.waves>=2&&e.first_wave_tick>source_ticks+24000,"genuine delayed first wave, not fixture-injected spawn");}else check(e.harvest_adds&&e.deliveries&&e.credits_delivered,"actual native cargo and refinery income observed");snprintf(p,sizeof p,".local/native-campaign-fidelity/%s.json",id);FILE*f=fopen(p,"w");check(f!=NULL,"summary evidence");fprintf(f,"{\"id\":\"%s\",\"house\":%u,\"mission\":9,\"framesComparedWholeCPU\":%llu,\"wholeCpuBytes\":%zu,\"startNativeFrame\":%llu,\"endNativeFrame\":%llu,\"startNativeTicks\":%llu,\"endNativeTicks\":%u,\"masterClocks\":%llu,\"nativeInstructions\":%llu,\"shots\":%llu,\"actualProjectiles\":%llu,\"actorHpDecreases\":%llu,\"actualCargoIncreases\":%llu,\"cargoAdded\":%llu,\"nativeRefineryDeliveries\":%llu,\"creditsDelivered\":%llu,\"acceptedScheduledDeployments\":%llu,\"firstWaveTick\":%llu,\"waveOwnerMask\":%u,\"harvestOwnerMask\":%u,\"deliveryOwnerMask\":%u,\"nativeOutcome\":%d,\"worldUnedited\":true,\"groundArrivalOwnerMask\":%u,\"groundArrivals\":%llu}\n",id,house,(unsigned long long)e.frames,sizeof oracle,(unsigned long long)source_frames,(unsigned long long)oracle.vdp.frames,(unsigned long long)source_ticks,dune_long(&oracle,0xc598),(unsigned long long)(oracle.master_cycles-initial.master_cycles),(unsigned long long)(oracle.steps-initial.steps),(unsigned long long)e.shots,(unsigned long long)e.projectiles,(unsigned long long)e.hp_decreases,(unsigned long long)e.harvest_adds,(unsigned long long)e.cargo_added,(unsigned long long)e.deliveries,(unsigned long long)e.credits_delivered,(unsigned long long)e.waves,(unsigned long long)e.first_wave_tick,e.wave_owner_mask,e.harvest_owner_mask,e.delivery_owner_mask,em_web_campaign.outcome,e.ground_owner_mask,(unsigned long long)e.ground_arrivals);fclose(f);printf("PASS %s: fullCPU%lluframes; projectile%llu HP%llu cargo%llu income%llu waves%llu tick%llu\n",id,(unsigned long long)e.frames,(unsigned long long)e.projectiles,(unsigned long long)e.hp_decreases,(unsigned long long)e.harvest_adds,(unsigned long long)e.deliveries,(unsigned long long)e.waves,(unsigned long long)e.first_wave_tick);fflush(stdout);}
int main(int argc,char**argv){mkdir(".local/native-campaign-fidelity",0755);unsigned lo=0,hi=3;if(argc>1){lo=(unsigned)atoi(argv[1]);hi=lo+1;check(lo<3,"house selector");}for(unsigned h=lo;h<hi;h++){load(h);char id[64];snprintf(id,sizeof id,"h%u-m9-own-wave",h);differential(id,40000,1);}return 0;}
